-- AIU course supply lists derived from the uploaded source PDFs as captured in the master specification.
do $$
declare aiu uuid; endo uuid; fixedc uuid; rem uuid; op uuid; lid uuid;
begin
select id into aiu from public.universities where name_en='Alamein International University';
select id into endo from public.courses where slug='endodontics';
select id into fixedc from public.courses where slug='fixed-prosthodontics';
select id into rem from public.courses where slug='removable-prosthodontics';
select id into op from public.courses where slug='operative-dentistry';
end $$;
